// The retained opening sentences were reviewed as definitions + concrete examples.
// Keep this selection explicit: do not apply a truncation rule to future CMS text.
const retainedOpeningIds = new Set([
  ...Array.from({ length: 124 }, (_, i) => `kb_${i + 957}`).filter(id => !['kb_966','kb_969','kb_970','kb_971'].includes(id)),
  'kb_966','kb_969','kb_970','kb_971',
]);
const rows = [];
for (const t of published) {
  const quote = t.quotation;
  let summary = overrides[t.id];
  let contextNote;
  let reason = summary ? '意味の核を先頭に置き、定義と必要な条件・例に整理' : undefined;
  if (quote) {
    contextNote = quotationNotes[quote.candidateId];
    assert.ok(contextNote, `Unreviewed quotation ${t.id}`);
    summary = `「${quote.translationText}」\n— ${quote.author}\n${quote.work}\n\n${contextNote}`;
    reason = '監査向け注記を読者向けの意味説明へ改稿。引用文・著作者・原典・権利情報を保全';
  } else if (!summary && retainedOpeningIds.has(t.id)) {
    summary = (t.summary.match(/[^。]+。/g) ?? [t.summary]).slice(0, 2).join('');
    reason = '定義と具体例を残し、重複する手順説明・一般的な免責を削減';
  }
  if (summary && summary !== t.summary) rows.push({ id: t.id, title: t.title, beforeSummary: t.summary, summary, ...(quote ? { beforeContextNote: quote.contextNote, contextNote } : {}), reason });
}
assert.equal(rows.filter(r => r.contextNote).length, 19);
assert.equal(source.subcategories.length, 36);
fs.writeFileSync('docs/content/theory-summary-review-20261019.json', JSON.stringify({ reviewedPublishedCount: published.length, categoryCount: new Set(published.map(t=>t.category_id)).size, subcategoryCount: source.subcategories.length, changes: rows }, null, 2) + '\n');
console.log(`Prepared ${rows.length} summary edits including 19 quotation explanations.`);
